async function envoyerFormulaire(formulaire) {
  const donnees = {
    nom: formulaire.nom.trim(),
    age: Number(formulaire.age)
  };
  if (!donnees.nom || !Number.isInteger(donnees.age)) {
    throw new Error("Donnée invalide");
  }
  const reponse = await fetch("/api/profil", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(donnees)
  });
  if (!reponse.ok) throw new Error("Transmission refusée");
  return reponse.json();
}

